    void send_error(const uint32_t id_task, const std::string & error, const enum error_type type = ERROR_TYPE_SERVER, int n_prompt_tokens = 0, int64_t n_gen = 0) {
        SRV_ERR("id = %d: %s\n", id_task, error.c_str());

        if (error_type_is_server_error(type)) {
